const items = $input.all();
const data = items.map(item => item.json);
const nextId = data.length > 0 ? data[data.length - 1].id : null;
const hasMore = data.length === 1000;

return [{
  json: {
    type: 'prediction',
    data: data,
    nextId: nextId,
    hasMore: hasMore,
    batchSize: data.length,
    columns: {
      dimensions: ['date','site','service','jour_semaine','annee','mois','trimestre','semaine','granularite'],
      volume: ['volume_tickets','tickets_termines','tickets_abandonnes'],
      rates: ['taux_abandon','taux_service','occupation_guichets','productivite_agent','taux_pause'],
      wait: ['duree_attente_moy','duree_attente_p90','duree_traitement_moy'],
      sla: ['sla_breach_count'],
      guichets: ['nb_guichets_actifs','flux_par_heure','tickets_par_guichet'],
      distribution: ['pct_moins5min','pct5a10min','pct10a20min','pct_plus20min'],
      peak: ['volume_heure_pointe'],
      metadata: ['is_prediction','created_at']
    },
    message: hasMore ? 'More data available. Send next request with lastId: ' + nextId : 'All prediction data retrieved'
  }
}];

// ── STEP 1: Detect if the question needs SQL or is conversational ────────
const question = $('Dashboard API').first().json.body.payload.question || '';

// Keywords that suggest a data question
const dataKeywords = [
  'show', 'give', 'list', 'count', 'average', 'avg', 'total', 'sum',
  'compare', 'top', 'worst', 'best', 'highest', 'lowest', 'rate',
  'ticket', 'wait', 'service', 'site', 'abandon', 'sla', 'breach',
  'occupation', 'productivit', 'guichet', 'predict', 'history',
  'montre', 'donne', 'liste', 'comparer', 'taux', 'moyenne', 'total'
];

const lower = question.toLowerCase();
const needsData = dataKeywords.some(kw => lower.includes(kw));

return [{
  json: {
    question: question,
    needsData: needsData,
    webhookBody: $('Dashboard API').first().json.body
  }
}];

// ── Clean and validate the SQL output ───────────────────────────────────
const raw = $input.first().json.output || '';

// Strip markdown fences, backticks, leading/trailing whitespace
let sqlQuery = raw
  .replace(/```sql/gi, '')
  .replace(/```/g, '')
  .replace(/^sql\s*/i, '')
  .trim();

// If it doesn't start with SELECT, try to extract it
if (!sqlQuery.toUpperCase().startsWith('SELECT')) {
  const match = sqlQuery.match(/SELECT[\s\S]+/i);
  if (match) {
    sqlQuery = match[0].trim();
  } else {
    // Not SQL at all — pass through as a direct answer
    return [{ json: { isCasual: true, answer: raw.trim() } }];
  }
}

// Block dangerous keywords
const dangerous = ['INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 'CREATE', 'TRUNCATE'];
const upperQuery = sqlQuery.toUpperCase();
for (const keyword of dangerous) {
  if (upperQuery.includes(keyword)) {
    return [{ json: { isCasual: true, answer: 'I cannot execute that type of query.' } }];
  }
}

// Ensure only allowed tables
const allowedTables = ['kpi_history', 'kpi_predictions'];
const foundTable = allowedTables.some(t => upperQuery.includes(t.toUpperCase()));
if (!foundTable) {
  return [{ json: { isCasual: true, answer: 'I can only query kpi_history or kpi_predictions.' } }];
}

// Add LIMIT if missing
if (!upperQuery.includes('LIMIT')) {
  sqlQuery = sqlQuery.replace(/;?\s*$/, '') + ' LIMIT 1000';
}

return [{ json: { query: sqlQuery, validated: true, isCasual: false } }];

// Collapse all query result rows into ONE item for the AI
const allRows = $input.all().map(i => i.json);

return [{
  json: {
    rows: allRows,
    rowCount: allRows.length,
    // Send max 50 rows to AI — enough for analysis, avoids token overflow
    sample: allRows.slice(0, 50),
    summary: {
      totalRows: allRows.length,
      truncated: allRows.length > 50
    }
  }
}];
